async function api(url,opt={}){const r=await fetch(url,{...opt,headers:{'Content-Type':'application/json','X-Requested-With':'Steady',...(opt.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok){const err=Error(d.error||'Request failed');err.status=r.status;throw err}return d}
function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
const weekdayLabels=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
function addPreferredWeekdays(form,selected=[]){
  const schedule=form.elements.schedule;if(!schedule)return null;
  const fieldset=document.createElement('fieldset');fieldset.className='weekday-picker';
  const legend=document.createElement('legend');legend.textContent='Preferred training weekdays (optional)';fieldset.append(legend);
  const options=document.createElement('div');options.className='weekday-options';
  weekdayLabels.forEach((label,value)=>{const row=document.createElement('label');row.className='check';const input=document.createElement('input');input.type='checkbox';input.name='preferredDay';input.value=String(value);input.checked=selected.includes(value);row.append(input,document.createTextNode(label));options.append(row)});
  const help=document.createElement('small');help.className='muted';help.setAttribute('aria-live','polite');fieldset.append(options,help);schedule.closest('label')?.after(fieldset);
  const update=()=>{const count=fieldset.querySelectorAll('[name="preferredDay"]:checked').length,expected=Number(schedule.value);const valid=count===0||count===expected;help.textContent=valid?(count?`The plan will schedule around these ${count} chosen days.`:'Leave all days clear to let your activity and recovery history guide training days.'):`Select exactly ${expected} days, or clear all days.`;fieldset.dataset.valid=String(valid)};
  fieldset.addEventListener('change',update);schedule.addEventListener('change',update);update();
  return{fieldset,values:()=>[...fieldset.querySelectorAll('[name="preferredDay"]:checked')].map(input=>Number(input.value)),isValid:()=>fieldset.dataset.valid==='true'};
}
