   sets.forEach((set,j)=>{const row=document.createElement('p');row.textContent=set.duration!=null?'Cardio: '+set.duration+' min · '+(set.distance||'—')+' '+(set.distanceUnit||'')+' · incline '+(set.incline||'0')+'%':'Set '+(j+1)+': '+(set.weight||'—')+' '+(set.unit||'')+' × '+(set.reps||'—');
     const edit=document.createElement('button');edit.className='ghost';edit.textContent='Edit';edit.onclick=()=>{el.querySelectorAll('[data-field]').forEach(x=>{if(x.type==='checkbox')x.checked=!!set[x.dataset.field];else x.value=set[x.dataset.field]??''});const b=el.querySelector('[data-save]');b.dataset.edit=String(j);b.textContent='Save correction';dirty=true};row.append(edit);list.append(row)});el.append(list);
