  list.querySelectorAll('[data-delete-upload]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this private image?'))return;try{await api('/api/uploads/'+b.dataset.deleteUpload,{method:'DELETE'});status.textContent='Private image deleted.';await refresh()}catch(e){status.textContent=e.message}});
