  const section=document.createElement('fieldset');section.className='meal-settings';
  section.innerHTML=`<legend>Meal and snack routine</legend><p class="muted">These times organize suggestions in your local time zone; they do not change your workout or imply a special fat-loss effect.</p>${[['mealTimeBreakfast','Breakfast','08:00'],['mealTimeLunch','Lunch','12:30'],['mealTimeSnack','Snack','15:30'],['mealTimeDinner','Dinner','18:30']].map(([key,label,fallback])=>`<label>${label} time<input type="time" name="${key}" value="${esc(state.profile[key]||fallback)}" required></label>`).join('')}<label>Usual workout time (optional)<input name="workoutTime" maxlength="80" value="${esc(state.profile.workoutTime||'')}" placeholder="18:00 or after work"></label><label>Food allergies (optional)<textarea name="allergies" maxlength="1000">${esc(state.profile.allergies||'')}</textarea></label><label>Dietary restrictions (optional)<textarea name="dietaryRestrictions" maxlength="1000">${esc(state.profile.dietaryRestrictions||'')}</textarea></label><p class="muted">Enter workout time as HH:mm to see before/after labels. When allergies or restrictions are entered, automatic food suggestions pause until foods can be checked safely. Your manual food log still works.</p>`;
