const renderSettingsBeforeBackups=renderSettings;
renderSettings=()=>{renderSettingsBeforeBackups();const host=$('#view-settings');if(!host||host.querySelector('#privateBackups'))return;host.insertAdjacentHTML('beforeend',`<section class="panel" id="privateBackups"><h2>Private off-site backups</h2><p class="muted">A daily copy of your records and attached screenshots is kept in private Azure storage. Each backup is checked by restoring it to a temporary location and validating its database and files.</p><p id="backupStatus" role="status" aria-live="polite">Checking backup status…</p><div class="actions"><button class="ghost" id="backupNow" type="button">Create backup now</button><button class="ghost" id="verifyBackup" type="button">Verify latest backup</button></div></section>`);const status=$('#backupStatus'),run=$('#backupNow'),verify=$('#verifyBackup');const refresh=async()=>{try{const s=await api('/api/backups/status');if(!s.enabled){status.textContent='Private backup storage is not connected yet.';run.disabled=true;verify.disabled=true;return}status.textContent=s.lastError||`Last backup: ${s.lastBackup?new Date(s.lastBackup).toLocaleString():'pending'} · Restore check: ${s.lastVerification?new Date(s.lastVerification).toLocaleString():'pending'}${s.running?' · Backup running':''}`;run.disabled=!!s.running;verify.disabled=!!s.running||!s.lastBackup}catch{status.textContent='Could not load backup status.'}};run.onclick=async()=>{run.disabled=true;status.textContent='Creating backup and checking its restore…';try{const r=await api('/api/backups/run',{method:'POST',body:'{}'});status.textContent=`Backup and restore check succeeded: ${new Date(r.createdAt).toLocaleString()} · ${r.uploadCount} screenshot(s)`}catch(e){status.textContent=e.message}await refresh()};verify.onclick=async()=>{verify.disabled=true;status.textContent='Checking the latest backup…';try{const r=await api('/api/backups/verify',{method:'POST',body:'{}'});status.textContent=`Restore check passed: ${new Date(r.createdAt).toLocaleString()} · ${r.uploadCount} screenshot(s)`}catch(e){status.textContent=e.message}await refresh()};refresh()};

const renderTodayBeforeRestOverride=renderToday;
renderToday=()=>{
  renderTodayBeforeRestOverride();
  if(!state?.check||state.workout||state.plan?.kind!=='recovery'||state.plan.status==='unstarted')return;
  const title=[...document.querySelectorAll('#view-today .panel h2')].find(heading=>heading.textContent===state.plan.title);
  const panel=title?.closest('.panel');if(!panel||panel.querySelector('#restDayOverrideNote'))return;
  const check=state.check,profile=state.profile||{},urgent=Number(check.systolic)>=180||Number(check.diastolic)>=120||['chest-pain','fainting','severe-breathlessness'].includes(check.symptoms),blocked=urgent||profile.clearance==='restricted'||profile.injuries||profile.restrictions||check.pain==='movement-pain'||check.soreness==='high'||check.energy==='low';
  const addChoice=(mode,label,primary=false)=>{const button=document.createElement('button');button.type='button';button.id=mode==='regular'?'regularRestOverride':'restDayOverride';button.className=primary?'primary':'ghost';button.textContent=label;button.onclick=()=>saveAction(()=>api('/api/plan/rest-day-override',{method:'POST',body:JSON.stringify({mode})}));panel.querySelector('.actions')?.before(button)};
  const note=document.createElement('p');note.id='restDayOverrideNote';note.className='muted';note.textContent=blocked?'Today’s check-in indicates that exercise should remain optional or paused; keep the recovery plan and its safety guidance.':'You can keep the planned rest day, take an easy walk, or—if energy is high—choose a regular session. Don’t make up missed workouts.';
  panel.querySelector('.actions')?.before(note);
  if(!blocked){if(check.energy==='high')addChoice('regular','Choose a regular workout',true);addChoice('light','Choose an easy 10–15 minute walk')}
};

let activeGymSlot=0;
const renderTodayBeforeGymFocus=renderToday;
renderToday=()=>{
  renderTodayBeforeGymFocus();
  if(state?.workout?.status!=='active')return;
  const panel=$('#startWorkout')?.closest('.panel');
  const exercises=[...(panel?.querySelectorAll('.exercise')||[])];
  if(!exercises.length)return;
  activeGymSlot=Math.max(0,Math.min(activeGymSlot,exercises.length-1));
  panel.classList.add('gym-focus');
  const heading=document.createElement('div');heading.className='gym-heading';
  heading.innerHTML='<p class="eyebrow">LIVE WORKOUT</p><h3 id="gymProgress"></h3><p class="muted" id="gymSaveStatus" role="status" aria-live="polite">Saved entries stay available after refresh.</p>';
  exercises[0].before(heading);
  const navigation=document.createElement('nav');navigation.className='gym-navigation';navigation.setAttribute('aria-label','Workout exercises');
  const previous=document.createElement('button'),next=document.createElement('button');
  previous.type=next.type='button';previous.className=next.className='ghost';previous.textContent='Previous';next.textContent='Next exercise';
  navigation.append(previous,next);exercises.at(-1).after(navigation);
  const show=slot=>{
    activeGymSlot=slot;
    exercises.forEach((exercise,index)=>{exercise.hidden=index!==slot;exercise.querySelectorAll('[data-save]').forEach(button=>button.classList.toggle('primary',index===slot))});
    $('#gymProgress').textContent=`Exercise ${slot+1} of ${exercises.length}: ${exercises[slot].querySelector('h3')?.textContent||''}`;
    previous.disabled=slot===0;next.disabled=slot===exercises.length-1;
  };
  previous.onclick=()=>show(Math.max(0,activeGymSlot-1));next.onclick=()=>show(Math.min(exercises.length-1,activeGymSlot+1));
  $('#startWorkout').hidden=true;
  show(activeGymSlot);
};

const renderTodayBeforeHierarchy=renderToday;
renderToday=()=>{
  renderTodayBeforeHierarchy();
  const view=$('#view-today');if(!view)return;
  if(state.workout?.status==='completed'){
    const button=$('#completeWorkout'),panel=button?.closest('.panel');
    $('#startWorkout')?.remove();button?.remove();
    if(panel&&state.workout.recap){const summary=document.createElement('p');summary.className='notice';summary.textContent=`Workout finished: ${state.workout.recap.counts.completed} completed, ${state.workout.recap.counts.partial} partial, ${state.workout.recap.counts.skipped} skipped, ${state.workout.recap.counts.unplanned||0} unplanned. See History for the saved recap.`;panel.querySelector('h2')?.after(summary)}
  }
  const action=!state.check?$('#checkin'):state.workout?.status==='active'?view.querySelector('.gym-focus .exercise:not([hidden]) [data-save]'):state.workout?.status==='completed'?null:state.plan?.status==='unstarted'?$('#confirmPlan'):$('#startWorkout');
  const panel=action?.closest('.panel');if(!panel)return;
  panel.classList.add('next-step');
  const heading=panel.querySelector('h2');if(heading){const cue=document.createElement('p');cue.className='eyebrow';cue.textContent='NEXT STEP';heading.before(cue)}
};

const wireTodayBeforeRecap=wireToday;
wireToday=()=>{
  wireTodayBeforeRecap();
  const finish=$('#completeWorkout');if(!finish||state.workout?.status!=='active')return;
  finish.textContent='Review and finish';
  finish.onclick=()=>{
    if(dirty){notice('Save or clear your unfinished entries before reviewing the workout.');return}
    $('#finishPreview')?.remove();
    const recap=summarizeWorkout(state.plan,state.workout);
    const panel=document.createElement('section');panel.id='finishPreview';panel.className='panel';
    panel.innerHTML=`<h2>Review today’s workout</h2><p class="muted">Check saved work before finishing. Choose an exercise to correct its entries; nothing is finalized until you confirm.</p><p>${recap.counts.completed} completed · ${recap.counts.partial} partial · ${recap.counts.skipped} skipped · ${recap.counts.unplanned||0} unplanned${recap.cardioMinutes?` · ${recap.cardioMinutes} cardio min`:''}${recap.durationMinutes!=null?` · about ${recap.durationMinutes} min elapsed`:''}</p><ul>${recap.entries.map((entry,slot)=>`<li><strong>${esc(entry.name)}</strong>: ${esc(entry.status)} · ${entry.status==='unplanned'?`${entry.logged} actual entries`:`${entry.logged} of ${entry.planned} ${entry.kind==='cardio'?'cardio entries':'sets'}`} <button type="button" class="ghost" data-correct-slot="${slot}">Correct</button></li>`).join('')}</ul><div class="actions"><button type="button" class="ghost" id="keepLogging">Keep logging</button><button type="button" class="primary" id="confirmFinish">Finish workout</button></div>`;
    finish.closest('.panel').after(panel);
    panel.querySelector('#keepLogging').onclick=()=>panel.remove();
    panel.querySelectorAll('[data-correct-slot]').forEach(button=>button.onclick=()=>{const slot=Number(button.dataset.correctSlot);if(recap.entries[slot]?.status==='unplanned'){$('#unplannedActivity')?.scrollIntoView({block:'start'});panel.remove();return}activeGymSlot=slot;renderToday();$('#gymProgress')?.scrollIntoView({block:'start'})});
    panel.querySelector('#confirmFinish').onclick=()=>{const data=structuredClone(state.workout);delete data.version;delete data.status;saveAction(()=>api('/api/workout',{method:'POST',body:JSON.stringify({data,version:state.workout.version,status:'completed'})}))};
    panel.scrollIntoView({behavior:'smooth',block:'start'});
  };
};

const renderHistoryBeforeRecap=renderHistory;
renderHistory=async()=>{
  await renderHistoryBeforeRecap();
  const cards=[...document.querySelectorAll('#view-history .panel:first-child article.exercise')];
  (state.workoutHistory||[]).forEach((workout,index)=>{
    const recap=workout.data.recap,card=cards[index];if(!recap||!card)return;
    const summary=document.createElement('p');summary.className='notice';
    summary.textContent=`Recap: ${recap.counts.completed} completed, ${recap.counts.partial} partial, ${recap.counts.skipped} skipped, ${recap.counts.unplanned||0} unplanned${recap.durationMinutes!=null?` · ${recap.durationMinutes} min elapsed`:''}${recap.cardioMinutes?` · ${recap.cardioMinutes} cardio min`:''}.`;
    card.querySelector('h3')?.after(summary);
  });
};

const renderSettingsBeforeEquipment=renderSettings;
renderSettings=()=>{
  renderSettingsBeforeEquipment();
  const host=$('#view-settings');if(!host||$('#equipmentProfiles'))return;
  const panel=document.createElement('section');panel.className='panel';panel.id='equipmentProfiles';
  const names=[...new Set([...(state.plan?.exercises||[]).map(x=>x.name),...(state.workoutHistory||[]).flatMap(w=>(w.data.exercises||[]).map(x=>x.name))])];
  panel.innerHTML=`<h2>Exercise equipment profiles</h2><p class="muted">Name the exact machine or equipment you use. Loads on different equipment stay separate; setup notes are private. Existing profiles keep their identity when a note changes.</p><datalist id="exerciseNames">${names.map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist><form id="equipmentProfileForm" class="stack"><label>Exact exercise<input name="exerciseName" list="exerciseNames" maxlength="120" required></label><label>Machine or equipment name<input name="equipmentName" maxlength="120" required placeholder="e.g. Movati Matrix chest press"></label><label>How load is shown<select name="loadMeaning"><option value="total">Total machine load</option><option value="per hand">Per hand</option><option value="per side">Per side</option><option value="assisted">Assisted weight</option></select></label><label>Seat, grip or setup note<textarea name="setupNote" maxlength="1000"></textarea></label><button class="ghost">Save equipment profile</button></form><div class="stack">${(state.exerciseProfiles||[]).map(profile=>`<article class="equipment-profile"><strong>${esc(profile.exerciseName)} · ${esc(profile.equipmentName)}</strong><p class="muted">${esc(profile.loadMeaning)} load</p><form data-profile-note="${profile.id}" class="stack"><label>Setup note<textarea name="setupNote" maxlength="1000">${esc(profile.setupNote)}</textarea></label><button class="ghost">Update note</button></form></article>`).join('')||'<p class="muted">No equipment profiles yet.</p>'}</div>`;
  host.append(panel);
  panel.querySelector('#equipmentProfileForm').onsubmit=e=>{e.preventDefault();saveAction(()=>api('/api/exercise-profiles',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))}))};
  panel.querySelectorAll('[data-profile-note]').forEach(form=>form.onsubmit=e=>{e.preventDefault();saveAction(()=>api('/api/exercise-profiles/'+form.dataset.profileNote,{method:'PUT',body:JSON.stringify({setupNote:form.elements.setupNote.value})}))});
};

const wireTodayBeforeEquipment=wireToday;
wireToday=()=>{
  wireTodayBeforeEquipment();
  if(state.workout?.status!=='active')return;
  document.querySelectorAll('#view-today .exercise[data-exercise-slot]').forEach(el=>{
    const slot=Number(el.dataset.exerciseSlot),index=activeWorkoutIndex(state.workout,slot),exercise=state.workout.exercises[index];
    if(!exercise)return;
    el.querySelector('.history-suggestion')?.remove();el.querySelector('.history-suggestion-action')?.remove();
    const profiles=(state.exerciseProfiles||[]).filter(profile=>profile.exerciseName===exercise.name);
    const area=document.createElement('div');area.className='equipment-choice';
    area.innerHTML=`<label>Equipment for new sets<select data-profile-ex="${index}" aria-label="Equipment for ${esc(exercise.name)}"><option value="">Unlabelled equipment — no comparable load suggestion</option>${profiles.map(profile=>`<option value="${profile.id}">${esc(profile.equipmentName)} · ${esc(profile.loadMeaning)}</option>`).join('')}</select></label><p class="muted" data-profile-details></p><p class="muted" data-profile-history></p>`;
    el.querySelector('.setrow')?.before(area);
    const select=area.querySelector('select'),details=area.querySelector('[data-profile-details]'),history=area.querySelector('[data-profile-history]');
    select.value=String(exercise.sets.at(-1)?.equipmentProfileId||'');
    const showProfile=()=>{
      const profile=profiles.find(item=>String(item.id)===select.value);
      details.textContent=profile?`${profile.loadMeaning} load · ${profile.setupNote||'No setup note yet.'}`:'Create an equipment profile in Settings for comparable load history.';
      history.replaceChildren();if(!profile)return;
      const previous=(state.workoutHistory||[]).filter(w=>w.day<state.day).flatMap(w=>(w.data.exercises||[]).filter(x=>x.name===exercise.name).flatMap(x=>[...(x.sets||[])].reverse().map(set=>({day:w.day,set})))).find(item=>Number(item.set.equipmentProfileId)===profile.id);
      if(!previous){history.textContent='No earlier set saved with this exact equipment.';return}
      const set=previous.set,summary=set.duration!=null?`${set.duration} min${set.distance?` · ${set.distance} ${set.distanceUnit||''}`:''}`:`${set.weight??'—'} ${set.unit||''} × ${set.reps??'—'}`;
      history.append(document.createTextNode(`Last comparable set on ${previous.day}: ${summary}. `));
      const use=document.createElement('button');use.type='button';use.className='ghost';use.textContent='Use comparable settings';
      use.onclick=()=>{for(const field of ['weight','reps','duration','distance','incline']){const input=el.querySelector(`[data-ex="${index}"][data-field="${field}"]`);if(input&&set[field]!=null){input.value=set[field];input.dispatchEvent(new Event('input',{bubbles:true}))}}};history.append(use);
    };
    select.onchange=showProfile;showProfile();
    const rows=[...el.querySelectorAll('.saved-sets p')].slice(1);
    rows.forEach((row,setIndex)=>{const id=exercise.sets[setIndex]?.equipmentProfileId,profile=(state.exerciseProfiles||[]).find(item=>item.id===Number(id));row.prepend(document.createTextNode(profile?`${profile.equipmentName} (${profile.loadMeaning}) · `:'Unlabelled equipment · '))});
  });
};

const renderTodayBeforeUnplanned=renderToday;
renderToday=()=>{
  renderTodayBeforeUnplanned();
  if(!state.workout||!['active','completed'].includes(state.workout.status))return;
  const host=$('#view-today'),panel=document.createElement('section');panel.id='unplannedActivity';panel.className='panel';
  const unplanned=state.workout.exercises.map((exercise,index)=>({exercise,index})).filter(item=>item.exercise.unplanned);
  panel.innerHTML=`<h2>Extra activity actually done</h2><p class="muted">Log exercise or cardio that was not on the confirmed plan. This does not change the original plan or add catch-up work.</p><form id="addUnplanned" class="stack"><label>Exercise or activity name<input name="name" maxlength="120" required placeholder="e.g. Bike or cable curl"></label><label>Type<select name="pattern"><option value="strength">Strength sets</option><option value="cardio">Cardio duration</option></select></label><button class="ghost">Add activity</button></form>${unplanned.map(({exercise,index})=>`<article class="unplanned-card"><h3>${esc(exercise.name)} · ${esc(exercise.pattern)}</h3><ul>${(exercise.sets||[]).map((set,setIndex)=>`<li>${exercise.pattern==='cardio'?`${esc(set.duration)} min${set.distance?` · ${esc(set.distance)} ${esc(set.distanceUnit||'')}`:''}`:`${esc(set.weight)} ${esc(set.unit||'')} × ${esc(set.reps)}`} <button type="button" class="ghost" data-edit-extra="${index}:${setIndex}">Edit</button> <button type="button" class="ghost" data-remove-extra="${index}:${setIndex}">Remove</button></li>`).join('')||'<li class="muted">No actual entries yet.</li>'}</ul><form class="stack" data-extra-set="${index}">${exercise.pattern==='cardio'?`<label>Actual minutes<input name="duration" type="number" min="0.1" max="1440" step="0.1" inputmode="decimal" required></label><label>Distance (optional)<input name="distance" type="number" min="0" step="0.01" inputmode="decimal"></label><label>Incline % (optional)<input name="incline" type="number" min="0" step="0.1" inputmode="decimal"></label>`:`<label>Actual weight (${esc(state.profile.units||'lb')})<input name="weight" type="number" min="0" step="0.5" inputmode="decimal" required></label><label>Actual reps<input name="reps" type="number" min="1" max="1000" inputmode="numeric" required></label>`}<label>Equipment profile (optional)<select name="equipmentProfileId"><option value="">Unlabelled equipment</option>${(state.exerciseProfiles||[]).filter(profile=>profile.exerciseName===exercise.name).map(profile=>`<option value="${profile.id}">${esc(profile.equipmentName)} · ${esc(profile.loadMeaning)}</option>`).join('')}</select></label><button class="ghost">Save actual ${exercise.pattern==='cardio'?'cardio':'set'}</button></form></article>`).join('')}`;
  host.insertBefore(panel,host.querySelector('#dailyMealSuggestions')||host.querySelector('#foodLog')?.closest('.panel')||null);
  panel.querySelector('#addUnplanned').onsubmit=e=>{e.preventDefault();const form=e.currentTarget,name=form.elements.name.value.trim(),pattern=form.elements.pattern.value;if(!name)return;saveAction(()=>{const data=structuredClone(state.workout);delete data.version;delete data.status;data.exercises.push({name,pattern,unplanned:true,sets:[]});return api('/api/workout',{method:'POST',body:JSON.stringify({data,version:state.workout.version,status:state.workout.status})})})};
  panel.querySelectorAll('[data-extra-set]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const index=Number(form.dataset.extraSet),editing=form.dataset.edit,exercise=state.workout.exercises[index],values=Object.fromEntries(new FormData(form));saveAction(()=>{const data=structuredClone(state.workout);delete data.version;delete data.status;const old=editing!==undefined?exercise.sets[Number(editing)]:null;const entry={...values,id:old?.id||crypto.randomUUID(),equipmentProfileId:Number(values.equipmentProfileId)||null,unit:state.profile.units,distanceUnit:state.profile.units==='kg'?'km':'mi',loggedAt:old?.loggedAt||new Date().toISOString()};if(editing!==undefined)data.exercises[index].sets[Number(editing)]=entry;else data.exercises[index].sets.push(entry);return api('/api/workout',{method:'POST',body:JSON.stringify({data,version:state.workout.version,status:state.workout.status})})})});
  panel.querySelectorAll('[data-edit-extra]').forEach(button=>button.onclick=()=>{const [index,setIndex]=button.dataset.editExtra.split(':').map(Number),form=panel.querySelector(`[data-extra-set="${index}"]`),set=state.workout.exercises[index].sets[setIndex];for(const [key,value] of Object.entries(set)){const input=form.elements[key];if(input)input.value=value??''}form.dataset.edit=String(setIndex);form.querySelector('button').textContent='Save correction';form.scrollIntoView({block:'center'})});
  panel.querySelectorAll('[data-remove-extra]').forEach(button=>button.onclick=()=>{if(!confirm('Remove this saved actual entry?'))return;const [index,setIndex]=button.dataset.removeExtra.split(':').map(Number);saveAction(()=>{const data=structuredClone(state.workout);delete data.version;delete data.status;data.exercises[index].sets.splice(setIndex,1);return api('/api/workout',{method:'POST',body:JSON.stringify({data,version:state.workout.version,status:state.workout.status})})})});
};

const renderSettingsBeforeFavourites=renderSettings;
renderSettings=()=>{
  renderSettingsBeforeFavourites();
  const host=$('#view-settings');if(!host||$('#savedMeals'))return;
  const foods=(state.foods||[]).filter(food=>food.available!==0&&food.preference==='preferred'),favourites=state.mealFavourites||[];
  const panel=document.createElement('section');panel.id='savedMeals';panel.className='panel';
  panel.innerHTML=`<h2>Saved meals and snacks</h2><p class="muted">Save a combination for later. Using it fills Today’s food form for review; it does not log food as eaten.</p><form id="favouriteForm" class="stack"><label>Favourite name<input name="name" maxlength="120" required></label><label>Meal<select name="meal"><option>breakfast</option><option>lunch</option><option>dinner</option><option>snack</option></select></label><fieldset><legend>Currently available preferred foods</legend>${foods.map(food=>`<label class="check"><input type="checkbox" name="foodId" value="${food.id}"> ${esc(food.name)}</label>`).join('')||'<p class="muted">Add available preferred foods in Food inventory first.</p>'}</fieldset><label>Portion or preparation (editable when logging)<input name="portion" maxlength="240"></label><button class="ghost">Save favourite</button></form><div class="stack">${favourites.map(favourite=>`<article class="saved-meal"><strong>${esc(favourite.name)} · ${esc(favourite.meal)}</strong><p>${esc(favourite.foodIds.map(id=>(state.foods||[]).find(food=>food.id===id)?.name||'Food no longer in inventory').join(' + '))}</p><p class="muted">${esc(favourite.portion||'Portion can be added when logging.')}</p><div class="actions"><button type="button" class="ghost" data-edit-favourite="${favourite.id}">Edit</button><button type="button" class="ghost" data-remove-favourite="${favourite.id}">Remove</button></div></article>`).join('')||'<p class="muted">No favourites saved yet.</p>'}</div>`;
  host.append(panel);
  const form=panel.querySelector('#favouriteForm');
  form.onsubmit=e=>{e.preventDefault();const body={name:form.elements.name.value,meal:form.elements.meal.value,portion:form.elements.portion.value,foodIds:[...form.querySelectorAll('[name="foodId"]:checked')].map(input=>Number(input.value))};const id=form.dataset.edit;saveAction(()=>api(id?'/api/meal-favourites/'+id:'/api/meal-favourites',{method:id?'PUT':'POST',body:JSON.stringify(body)}))};
  panel.querySelectorAll('[data-edit-favourite]').forEach(button=>button.onclick=()=>{const favourite=favourites.find(item=>item.id===Number(button.dataset.editFavourite));if(!favourite)return;form.dataset.edit=String(favourite.id);form.elements.name.value=favourite.name;form.elements.meal.value=favourite.meal;form.elements.portion.value=favourite.portion;form.querySelectorAll('[name="foodId"]').forEach(input=>input.checked=favourite.foodIds.includes(Number(input.value)));form.querySelector('button').textContent='Save changes';form.scrollIntoView({block:'start'})});
  panel.querySelectorAll('[data-remove-favourite]').forEach(button=>button.onclick=()=>{if(!confirm('Remove this saved meal? Food already logged will stay in History.'))return;saveAction(()=>api('/api/meal-favourites/'+button.dataset.removeFavourite,{method:'DELETE'}))});
};

const renderTodayBeforeFavourites=renderToday;
renderToday=()=>{
  renderTodayBeforeFavourites();
  const form=$('#foodLog'),favourites=state.mealFavourites||[];if(!form||!favourites.length||$('#todayFavourites'))return;
  const restricted=!!(String(state.profile.allergies||'').trim()||String(state.profile.dietaryRestrictions||'').trim());
  const byId=new Map((state.foods||[]).map(food=>[food.id,food]));
  const panel=document.createElement('section');panel.id='todayFavourites';panel.className='panel';
  panel.innerHTML=`<h2>Saved meal ideas</h2><p class="muted">Only currently available preferred foods are offered. Review and edit portions before logging what you actually ate.</p>${restricted?'<p class="notice">Review your allergies and dietary restrictions before reusing a saved meal; automatic suggestions are paused.</p>':''}${favourites.map(favourite=>{const usable=!restricted&&favourite.foodIds.every(id=>{const food=byId.get(id);return food&&food.available!==0&&food.preference==='preferred'});return `<article class="meal-idea"><div><strong>${esc(favourite.name)} · ${esc(favourite.meal)}</strong><p>${esc(favourite.foodIds.map(id=>byId.get(id)?.name||'Food no longer in inventory').join(' + '))}</p><small>${usable?esc(favourite.portion||'Edit the portion before logging.'):'Needs review in Settings before reuse.'}</small></div>${usable?`<button type="button" class="ghost" data-use-favourite="${favourite.id}">Use favourite</button>`:''}</article>`}).join('')}`;
  form.closest('.panel').before(panel);
  panel.querySelectorAll('[data-use-favourite]').forEach(button=>button.onclick=()=>{const favourite=favourites.find(item=>item.id===Number(button.dataset.useFavourite));if(!favourite)return;form.elements.meal.value=favourite.meal;form.elements.item.value=favourite.foodIds.map(id=>byId.get(id).name).join(' + ');form.elements.portion.value=favourite.portion;form.elements.item.dispatchEvent(new Event('input',{bubbles:true}));form.scrollIntoView({block:'center'});form.elements.portion.focus()});
};

const renderHistoryBeforeWeekly=renderHistory;
renderHistory=async()=>{
  await renderHistoryBeforeWeekly();
  const host=$('#view-history');if(!host||$('#weeklyReview'))return;
  const panel=document.createElement('section');panel.id='weeklyReview';panel.className='panel';
  panel.innerHTML=`<h2>Weekly review</h2><p class="muted">Choose any day in the week to review. Missing entries stay missing; this review does not change your workout or food targets.</p><form id="weekChoice" class="stack"><label>Week containing<input type="date" name="week" max="${esc(state.day)}" value="${esc(state.day)}" required></label><button class="ghost">Show week</button></form><div id="weekResults" role="status">Loading recorded week…</div>`;
  host.prepend(panel);
  const form=panel.querySelector('#weekChoice'),results=panel.querySelector('#weekResults');
  const loadWeek=async()=>{results.textContent='Loading recorded week…';try{const review=await api('/api/weekly-review?week='+encodeURIComponent(form.elements.week.value));const covered=review.elapsedDays,trend=(name,data)=>`${name}: ${data.days} of ${covered} elapsed days recorded${data.days?` · ${data.first} to ${data.last} ${esc(data.unit)}`:''}`;results.innerHTML=`<h3>${esc(review.start)}–${esc(review.end)}</h3><p>Workouts: ${review.workouts.completed} completed, ${review.workouts.active} active/partial; ${review.workouts.plannedRest} planned recovery days recorded.</p><p>Steps: ${review.steps.days} of ${covered} elapsed days recorded${review.steps.average!=null?` · ${review.steps.average.toLocaleString()} average on recorded days`:''}.</p><p>${trend('Weight',review.weight)}</p><p>${trend('Waist',review.waist)}</p><p>Food check-ins: ${review.food.days} of ${covered} elapsed days · ${review.food.onTrack} on track, ${review.food.partly} partly, ${review.food.offTrack} off track. “On track” share: ${review.food.days?Math.round(review.food.onTrack/review.food.days*100)+'% of recorded food check-ins':'not enough entries'}.</p><h4>Comparable strength entries</h4>${review.strength.length?`<ul>${review.strength.map(item=>{const profile=(state.exerciseProfiles||[]).find(p=>p.id===item.equipmentProfileId);return `<li>${esc(item.name)}${profile?` · ${esc(profile.equipmentName)}`:' · unlabelled equipment'}: ${esc(item.first.weight)} ${esc(item.first.unit)} × ${esc(item.first.reps)} on ${esc(item.first.day)} → ${esc(item.last.weight)} ${esc(item.last.unit)} × ${esc(item.last.reps)} on ${esc(item.last.day)}</li>`}).join('')}</ul>`:'<p class="muted">No exercise has comparable entries on two recorded days this week.</p>'}<p class="muted">${esc(review.note)}</p>`}catch(error){results.textContent=error.message}};
  form.onsubmit=e=>{e.preventDefault();loadWeek()};loadWeek();
};

const renderSettingsBeforePreferredDays=renderSettings;
renderSettings=()=>{
  renderSettingsBeforePreferredDays();
  const form=$('#settings');if(!form||form.querySelector('.weekday-picker'))return;
  const picker=addPreferredWeekdays(form,(state.profile.preferredDays||[]).map(Number));
  if(!picker)return;
  form.onsubmit=e=>{e.preventDefault();if(!picker.isValid()){picker.fieldset.querySelector('input')?.focus();return}const body={...state.profile,...Object.fromEntries(new FormData(form)),preferredDays:picker.values()};saveAction(()=>api('/api/profile',{method:'PUT',body:JSON.stringify(body)}))};
};

const renderTodayWithExerciseCatalog=renderToday;
renderToday=()=>{
  renderTodayWithExerciseCatalog();
  const attribution=state.plan?.catalogAttribution,host=$('#view-today');
  if(!host)return;
  const panel=host.querySelector('#startWorkout')?.closest('.panel')||host.querySelector('#confirmPlan')?.closest('.panel');
  if(!state.workout&&state.plan?.status==='confirmed'&&panel&&state.plan.exercises?.some(exercise=>exercise.pattern!=='cardio'&&exercise.substitutions?.some(option=>option.name!==exercise.name&&option.pattern===exercise.pattern))){
    const actions=panel.querySelector('.actions');
    if(actions&&!panel.querySelector('#anotherWorkout')){
      const button=document.createElement('button');button.type='button';button.id='anotherWorkout';button.className='ghost';button.textContent='Show another workout';
      button.onclick=()=>saveAction(()=>api('/api/plan/alternative',{method:'POST',body:'{}'}));
      actions.before(button);
      const previous=(state.workoutHistory||[]).find(workout=>workout.day<state.day&&(workout.status==='completed'||workout.data?.exercises?.some(exercise=>exercise.sets?.length)));
      const names=new Set((previous?.data?.exercises||[]).map(exercise=>exercise.name));
      if(state.plan.exercises.some(exercise=>names.has(exercise.name))){
        const note=document.createElement('p');note.className='muted';note.textContent='Some exercises match your last workout. Tap Show another workout for a different suitable mix before starting.';button.before(note);
      }
    }
  }
  if(attribution&&panel&&!panel.querySelector('#exerciseCatalogCredit')){
    const note=document.createElement('p');note.id='exerciseCatalogCredit';note.className='muted';
    note.append('Optional exercise alternatives use catalog data from ');
    const link=document.createElement('a');link.href=attribution.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='ExerciseAPI';note.append(link);
    note.append(' under CC BY 4.0. The app keeps workout programming, equipment filtering, and safety rules local.');panel.append(note);
  }
  if(!state.workout&&state.plan?.status==='confirmed'&&panel){
    const selectors=new Map();
    panel.querySelectorAll('.exercise').forEach((card,slot)=>{
      const exercise=state.plan.exercises[slot],options=exercise?.substitutions||[];
      if(!options.length)return;
      const label=document.createElement('label');label.className='catalog-choice';
      label.textContent=`Choose an exercise for ${exercise.name}`;
      const select=document.createElement('select');select.setAttribute('aria-label',`Exercise choice for ${exercise.name}`);
      const planned=document.createElement('option');planned.value='';planned.textContent=`Keep planned: ${exercise.name}`;select.append(planned);
      for(const option of options){if(option.name===exercise.name)continue;const item=document.createElement('option');item.value=option.name;item.textContent=option.equipment?`${option.name} · ${option.equipment}`:option.name;select.append(item)}
      const preview=document.createElement('p');preview.className='muted';preview.textContent='Choose an option before starting. Your choice is saved when you tap Start workout.';
      select.onchange=()=>{const option=options.find(item=>item.name===select.value);preview.textContent=option?`${option.name}${option.equipment?` · ${option.equipment}`:''}${option.cue?` · ${option.cue}`:''}`:'The planned exercise will be used.'};
      label.append(select);card.append(label,preview);selectors.set(slot,select);
    });
    const start=panel.querySelector('#startWorkout');
    if(start&&selectors.size)start.onclick=()=>saveAction(()=>api('/api/workout',{method:'POST',body:JSON.stringify({
      data:{exercises:state.plan.exercises.map((exercise,slot)=>{
        const choice=(exercise.substitutions||[]).find(option=>option.name===selectors.get(slot)?.value);
        return choice?{name:choice.name,pattern:exercise.pattern,muscles:choice.muscles,equipment:choice.equipment,cue:choice.cue,source:choice.source,sourceId:choice.sourceId,license:choice.license,slot,substitutedFrom:exercise.name,sets:[]}:{name:exercise.name,pattern:exercise.pattern,slot,sets:[]};
      }),startedAt:new Date().toISOString()},status:'active'
    })}));
  }
  if(!state.workout)return;
  host.querySelectorAll('.exercise[data-exercise-slot]').forEach(card=>{
    const slot=Number(card.dataset.exerciseSlot),index=activeWorkoutIndex(state.workout,slot),exercise=state.workout.exercises[index];
    if(!exercise?.source||!exercise.equipment||card.querySelector('.catalog-exercise-note'))return;
    const details=card.querySelector('.muted');
    if(details)details.textContent=`${exercise.sets?.length||state.plan.exercises[slot].sets} sets · ${exercise.reps||state.plan.exercises[slot].reps} · ${exercise.rest||state.plan.exercises[slot].rest} · ${exercise.muscles||state.plan.exercises[slot].muscles}`;
    const cue=card.querySelector('small');
    if(cue&&exercise.cue)cue.textContent=`${exercise.cue} Keep breathing continuously; use a comfortable range and stop if you feel pain.`;
    const note=document.createElement('p');note.className='muted catalog-exercise-note';note.textContent=`Equipment: ${exercise.equipment}. Keep earlier performance under ${exercise.substitutedFrom||'the previous movement'}; this is a separate exercise history.`;card.append(note);
  });
};
